function filtered(items, keys) { const q = localFilter.toLowerCase(); return !q ? items : items.filter(item => keys.some(key => String(item[key] || "").toLowerCase().includes(q))); }
function bookingTable(rows) {
  return `<div class="table-wrap"><table class="data-table"><thead><tr><th>Booking ID</th><th>Customer</th><th>Vehicle</th><th>Package</th><th>Date &amp; Time</th><th>Price</th><th>Payment</th><th>Status</th><th>Actions</th></tr></thead><tbody>${rows.length ? rows.map(b=>`<tr><td><strong>${b.id}</strong></td><td><div class="customer-cell">${tinyAvatar(b.customer,b.initials)}<div><strong>${escapeHtml(b.customer)}</strong><span class="subtext">${escapeHtml(b.phone)}</span></div></div></td><td>${escapeHtml(b.vehicle)}</td><td>${escapeHtml(b.package)}</td><td>${b.date}<span class="subtext">${b.time}</span></td><td>${formatMoney(b.price)}</td><td>${statusBadge(b.payment)}</td><td>${statusBadge(b.status)}</td><td><div class="row-actions"><button class="row-action" title="View booking" data-action="view-booking" data-id="${b.id}">${icon("eye")}</button><button class="row-action" title="Delete booking" data-action="delete-booking" data-id="${b.id}">${icon("trash-2")}</button></div></td></tr>`).join("") : `<tr><td colspan="9"><div class="empty-state">No bookings match your current filters.</div></td></tr>`}</tbody></table></div><div class="pagination"><span>Showing ${rows.length} of ${store.bookings.length} bookings</span><div class="pagination-buttons"><button class="page-dot active">1</button><button class="page-dot">2</button><button class="page-dot">›</button></div></div>`;
}
function bookingsPage() {
  let rows = bookingFilter === "All" ? store.bookings : store.bookings.filter(b => b.status === bookingFilter);
  rows = filtered(rows,["id","customer","phone","vehicle","package","status","payment"]);
  const tabs = ["All","Pending","Confirmed","Assigned","In Progress","Completed","Cancelled"];
  return `<section class="page-transition">${pageHeader("Bookings", "Schedule, track, and manage every customer appointment.", `<button class="outline-button" type="button" data-action="export">${icon("download")} Export</button><button class="primary-button" type="button" data-open-modal="booking">${icon("plus")} Create Booking</button>`)}<div class="toolbar"><label class="local-search">${icon("search")}<input id="localSearch" value="${escapeHtml(localFilter)}" placeholder="Search bookings, customer, vehicle..." /></label><div class="toolbar-actions"><button class="filter-button" type="button" data-action="filter-info">${icon("list-filter")} Filters</button><button class="filter-button" type="button" data-action="columns">${icon("columns-3")} Columns</button></div></div><div class="tabs">${tabs.map(tab=>`<button class="tab ${bookingFilter===tab?"active":""}" type="button" data-booking-tab="${tab}">${tab}${tab === "Pending" ? " (5)" : ""}</button>`).join("")}</div><section class="panel data-panel">${bookingTable(rows)}</section></section>`;
}

