function reportsPage() { return `<section class="page-transition">${pageHeader("Reports", "Track performance, identify trends, and make better decisions every day.", `<button class="primary-button" type="button" data-action="generate-report">${icon("file-down")} Generate Report</button>`)}<div class="reports-grid"><section class="panel chart-panel"><div class="panel-header"><h2>Revenue &amp; Profit</h2><button class="chart-select" type="button" data-action="change-chart">Last 30 days ${icon("chevron-down")}</button></div>${revenueChart()}</section><aside class="report-metrics"><section class="panel report-metric"><div><small>Total Revenue</small><strong>${formatMoney(68750)}</strong></div><b>+15.7%</b></section><section class="panel report-metric"><div><small>Operating Expenses</small><strong>${formatMoney(18520)}</strong></div><b>+4.1%</b></section><section class="panel report-metric"><div><small>Net Profit</small><strong>${formatMoney(50230)}</strong></div><b>+21.3%</b></section></aside></div><section class="panel summary-card" style="margin-top:14px"><div class="panel-header"><h2>Export center</h2><span class="subtext">Create a share-ready version of the selected report.</span></div><div class="export-list"><div class="export-option"><span>${icon("file-text")} Daily Operations Report</span><button type="button" data-action="export">Download PDF</button></div><div class="export-option"><span>${icon("sheet")} Monthly Revenue Report</span><button type="button" data-action="export">Export CSV</button></div><div class="export-option"><span>${icon("users-round")} Customer Retention Report</span><button type="button" data-action="export">Print</button></div><div class="export-option"><span>${icon("boxes")} Inventory Usage Report</span><button type="button" data-action="export">Export Excel</button></div></div></section></section>`; }

